import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Run history","description":"View past Flow executions and trace errors.","frontmatter":{"title":"Run history","description":"View past Flow executions and trace errors."},"headers":[],"relativePath":"en/flows/durchlaufhistorie.md","filePath":"en/flows/durchlaufhistorie.md","lastUpdated":1787319236000}'),s={name:"en/flows/durchlaufhistorie.md"};function n(i,t,l,h,d,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="run-history" tabindex="-1">Run history <a class="header-anchor" href="#run-history" aria-label="Permalink to &quot;Run history&quot;">​</a></h1><p>Every execution of a Flow is called a <strong>run</strong>. The <strong>History</strong> tab in a Flow shows past ones.</p><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Heading: <strong>Previous executions</strong>.</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Start time</strong></td><td>When the execution began</td></tr><tr><td><strong>Since start</strong></td><td>Elapsed time, relative</td></tr><tr><td><strong>Duration</strong></td><td>How long it ran</td></tr><tr><td><strong>Steps</strong></td><td>Number of steps executed</td></tr><tr><td><strong>Status</strong></td><td>Result</td></tr></tbody></table><p>Via <strong>Open</strong> you see a run in detail, via <strong>Refresh</strong> you reload the list.</p><p>Times appear relative: <em>Just now</em>, <em>{n} minutes ago</em>, <em>{n} hours ago</em>, <em>{n} days ago</em>. If no timestamp is known: <em>Date unknown</em>.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Done</strong> / <strong>Completed</strong></td><td>Ran through fully</td></tr><tr><td><strong>Error</strong> / <strong>Failed</strong></td><td>Aborted</td></tr><tr><td><strong>In progress</strong></td><td>Currently running</td></tr><tr><td><strong>Waiting</strong></td><td>Waiting on an event</td></tr><tr><td><strong>Created</strong></td><td>Set up, not yet started</td></tr><tr><td><strong>Test run</strong></td><td>A test run, not a real execution</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">&quot;Waiting&quot; usually isn&#39;t a problem</p><p>This status occurs by design when a Flow is waiting for something — a <a href="/en/flows/seiten-in-flows">page</a> that no one has submitted yet, or the end of a <strong>Wait</strong> step.</p><p>If waiting runs pile up, though, check whether the associated links actually reached the right people.</p></div><h2 id="viewing-a-run" tabindex="-1">Viewing a run <a class="header-anchor" href="#viewing-a-run" aria-label="Permalink to &quot;Viewing a run&quot;">​</a></h2><p>When you open one, the editor shows the data of that run instead of the empty blueprint:</p><blockquote><p><strong>Displaying previous executions</strong></p><p><em>This is data from a previous Flow execution. It was loaded automatically to illustrate the Flow&#39;s behavior.</em></p></blockquote><p>Displayed are <strong>Executed at</strong>, <strong>Loaded at</strong>, <strong>Status</strong>, and <strong>Steps</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Select other</strong></td><td>Switches to a different run</td></tr><tr><td><strong>Remove</strong></td><td>Leaves the data view</td></tr></tbody></table><p>The selection dialog is called <em>Select execution</em>; without data it shows <em>No executions found</em>.</p><div class="tip custom-block"><p class="custom-block-title">The editor shows real values</p><p>In history mode, you see at every step what actually ran — not the configuration. This is the fastest way to understand why a Flow behaved the way it did.</p></div><h2 id="tracing-errors" tabindex="-1">Tracing errors <a class="header-anchor" href="#tracing-errors" aria-label="Permalink to &quot;Tracing errors&quot;">​</a></h2><p>On every step:</p><table tabindex="0"><thead><tr><th>Action</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Show details</strong></td><td>Input and output data of the step</td></tr><tr><td><strong>Show error details</strong></td><td>The error message</td></tr></tbody></table><p>A tried-and-tested approach:</p><ol><li><strong>Where does it break off?</strong> The <em>Steps</em> column shows how far the Flow got.</li><li><strong>What came in?</strong> Check the output at the last successful step.</li><li><strong>What was expected?</strong> Often a format doesn&#39;t match.</li><li><strong>Correct and repeat</strong> via <strong>Restart</strong> — same input, changed configuration.</li></ol><h2 id="what-end-users-see" tabindex="-1">What end users see <a class="header-anchor" href="#what-end-users-see" aria-label="Permalink to &quot;What end users see&quot;">​</a></h2><p>If a Flow fails while someone is filling in a page, this appears there:</p><blockquote><p><strong>This process step could not be loaded</strong></p><p><em>The current step could not be executed due to a faulty configuration or an invalid value.</em></p><p><em>Please contact the person responsible for this process or your organization&#39;s administrator.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">This message is your cue</p><p>If someone reports this text, go into the history of the affected Flow. The failed run is at the very top — along with the step where it failed.</p></div><h2 id="error-notifications" tabindex="-1">Error notifications <a class="header-anchor" href="#error-notifications" aria-label="Permalink to &quot;Error notifications&quot;">​</a></h2><p>If a run fails, ApptiveGrid sends an email. The subject names the Flow; the body contains the Flow name, Space name, and the error message of the step where it broke.</p><p><strong>Recipients</strong> are everyone with the <strong>Manage</strong> role in the Space, plus the Flow&#39;s owner.</p><p>There are two versions of the email — the text tells you which case applies:</p><table tabindex="0"><thead><tr><th>The text says …</th><th>Meaning</th></tr></thead><tbody><tr><td>An error occurred, check the details</td><td>A single failure; the Flow keeps running</td></tr><tr><td><strong>The Flow was stopped</strong> and needs your attention</td><td>The Flow is switched off and won&#39;t run again until switched back on</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Three identical errors switch the Flow off</p><p>If the last three runs fail with the <strong>identical</strong> error message, ApptiveGrid switches the Flow off — the <a href="/en/flows/was-ist-ein-flow#switching-on-and-off">switch</a> flips to <em>off</em>. After that, no event triggers a run until you switch it back on by hand.</p><p>This particular email is your cue: fix the cause before switching it back on — otherwise, after three more events, the same three failures pile up and the Flow switches off again.</p><p>A successful run, or a failure with a different message in between, resets the count. A Flow that fails every other time keeps running — and keeps sending emails.</p></div><div class="tip custom-block"><p class="custom-block-title">Who doesn&#39;t get the email</p><p>People with <strong>Edit</strong> or <strong>View</strong> don&#39;t receive error notifications, even if they helped build the Flow. Whoever is responsible for a live Flow needs the <a href="/en/zusammenarbeit/rollen">Manage</a> role — otherwise they also won&#39;t be able to switch it back on afterward.</p></div><p>An exceeded quota — such as the number of Flow steps included in the plan — switches the Flow off immediately, without waiting for three attempts.</p><h2 id="check-in-regularly" tabindex="-1">Check in regularly <a class="header-anchor" href="#check-in-regularly" aria-label="Permalink to &quot;Check in regularly&quot;">​</a></h2><p>Even so, check the history of live Flows regularly — especially in the first few days after a change. Not every unwanted run is an error: a Flow that runs too often, or with wrong values, is technically successful and doesn&#39;t trigger an email.</p><div class="tip custom-block"><p class="custom-block-title">Too many runs is also a finding</p><p>If the list grows faster than expected, the trigger usually isn&#39;t right:</p><ul><li><em>Entry was changed</em> without a field condition starts on every little thing</li><li>An action that writes to the triggering Grid starts the Flow again</li><li>A <a href="/en/grids/csv-import">CSV import</a> triggers once per row</li></ul></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/testen">Testing Flows</a></li><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common error messages</a></li></ul>',39)])])}const p=e(s,[["render",n]]);export{g as __pageData,p as default};
